package com.pablo.controlgastos;

import android.app.Notification;import android.content.ComponentName;import android.os.Bundle;import android.service.notification.NotificationListenerService;import android.service.notification.StatusBarNotification;import java.text.Normalizer;import java.text.SimpleDateFormat;import java.util.*;import java.util.regex.*;

public class BankNotificationListener extends NotificationListenerService {
 private static volatile BankNotificationListener activeInstance;
 private static final Pattern MONEY=Pattern.compile("(?i)(U\\$S|USD|US\\$|\\$U|UYU|\\$)\\s*([0-9]+(?:[.,][0-9]{1,2})?|[0-9]{1,3}(?:[. ][0-9]{3})+(?:,[0-9]{1,2})?)");
 private static final Pattern LABELED_MONEY=Pattern.compile("(?i)(?:importe|monto|total|d[eé]bito|cr[eé]dito|valor)\\s*:?\\s*(U\\$S|USD|US\\$|\\$U|UYU|\\$)\\s*([0-9][0-9., ]*)");
 private static final Pattern BROU_IMPORTE=Pattern.compile("(?i)Importe\\s*:\\s*(UYU|USD|U\\$S|US\\$|\\$U|\\$)\\s*([0-9][0-9., ]*)"),BROU_COMERCIO=Pattern.compile("(?i)Comercio\\s*:\\s*([^\\n\\r]+)"),BROU_APROBADO=Pattern.compile("(?i)Aprobado\\s*:\\s*([0-9A-Za-z-]+)"),BROU_FECHA=Pattern.compile("(?i)Fecha\\s*:\\s*(\\d{4}-\\d{2}-\\d{2}\\s+\\d{2}:\\d{2}:\\d{2})"),BROU_EMAIL_OPERATION=Pattern.compile("(?i)N[uú]mero\\s+de\\s+operaci[oó]n\\s*:\\s*([0-9A-Za-z-]+)"),BROU_EXECUTION_DATE=Pattern.compile("(?i)Fecha\\s+de\\s+ejecuci[oó]n\\s*:\\s*(\\d{2}/\\d{2}/\\d{4}\\s+\\d{2}:\\d{2}:\\d{2})"),PAGANZA_SERVICE=Pattern.compile("(?i)(?:servicio|empresa|comercio|beneficiario|concepto)\\s*:\\s*([^\\n\\r]+)"),PAGANZA_REFERENCE=Pattern.compile("(?i)(?:referencia|operaci[oó]n|comprobante|transacci[oó]n)\\s*:?\\s*([0-9A-Za-z-]+)"),TRANSFER_DETAIL=Pattern.compile("(?im)^(?:beneficiario|destinatario|destino|receptor|titular|nombre|asunto|concepto|detalle|motivo|referencia|cuenta destino|cuenta receptora|ordenante|remitente|origen)\\s*:\\s*(.+)$");
 @Override public void onListenerConnected(){super.onListenerConnected();activeInstance=this;HourlyNotificationCheckReceiver.schedule(this);scanActiveNotifications();}@Override public void onListenerDisconnected(){activeInstance=null;super.onListenerDisconnected();}@Override public void onDestroy(){activeInstance=null;super.onDestroy();}public static void hourlyCheck(){BankNotificationListener i=activeInstance;if(i!=null)i.scanActiveNotifications();}public static boolean isConnected(){return activeInstance!=null;}public static boolean scanNow(){BankNotificationListener i=activeInstance;if(i==null)return false;i.scanActiveNotifications();return true;}public static void requestListenerReconnect(){try{requestRebind(new ComponentName("com.pablo.controlgastos.secure","com.pablo.controlgastos.BankNotificationListener"));}catch(Exception ignored){}}private void scanActiveNotifications(){try{StatusBarNotification[]a=getActiveNotifications();if(a!=null)for(StatusBarNotification s:a)processNotification(s);}catch(Exception ignored){}}@Override public void onNotificationPosted(StatusBarNotification sbn){processNotification(sbn);}
 private void processNotification(StatusBarNotification sbn){if(sbn==null||sbn.getNotification()==null)return;Bundle e=sbn.getNotification().extras;String title=s(e.getCharSequence(Notification.EXTRA_TITLE)),full=collectNotificationText(e);if(full.isEmpty())return;String all=title+"\n"+full,norm=normalizeKey(full),titleNorm=normalizeKey(title),pkg=sbn.getPackageName()==null?"":sbn.getPackageName(),pkgNorm=pkg.toLowerCase(Locale.ROOT);boolean strongBrou=isStrongApprovedBrouPurchase(title,full,norm);if(!strongBrou&&BlacklistRules.matches(this,all))return;boolean fromPaganza=pkgNorm.contains("paganza")||titleNorm.contains("paganza"),mentionsPaganza=norm.contains("paganza");if(fromPaganza){processPaganza(sbn,title,full,norm);return;}if(mentionsPaganza)return;boolean custom=DetectionRules.matches(this,all);processBankNotification(sbn,title,full,norm,custom,strongBrou);}
 private boolean isStrongApprovedBrouPurchase(String title,String full,String norm){if(norm.contains("rechaz")||norm.contains("anulad"))return false;return BROU_IMPORTE.matcher(full).find()&&BROU_APROBADO.matcher(full).find()&&(BROU_COMERCIO.matcher(full).find()||normalizeKey(title).contains("compra")||norm.contains("compra"));}
 private void processBankNotification(StatusBarNotification sbn,String title,String full,String norm,boolean custom,boolean strongBrou){boolean income=isIncomeNotification(norm),outgoing=isOutgoingTransfer(norm),expense=isExpenseNotification(norm);if(!strongBrou&&!custom&&!income&&!expense&&!outgoing)return;if(norm.contains("anulad")||norm.contains("rechaz")||norm.contains("fallida")||norm.contains("fallido")||norm.contains("pendiente"))return;String[]money=findBestMoney(full);if(money==null)return;String type=income&&!outgoing?"INGRESO":"GASTO";saveBankMovement(sbn,title,full,money[0],money[1],type);}
 private boolean isIncomeNotification(String n){return n.contains("transferencia recibida")||n.contains("transferencia recib")||n.contains("recibiste")||n.contains("acredit")||n.contains("deposito")||n.contains("ingreso")||n.contains("cobro recibido")||n.contains("te transfirieron")||n.contains("devolucion")||n.contains("reintegro")||n.contains("reembolso");}
 private boolean isOutgoingTransfer(String n){return n.contains("transferencia enviada")||n.contains("transferencia realizada")||n.contains("transferiste")||n.contains("enviaste")||n.contains("giro enviado")||n.contains("debito por transferencia");}
 private boolean isExpenseNotification(String n){return n.contains("compra")||n.contains("pago")||n.contains("debito")||n.contains("consumo")||n.contains("transaccion")||n.contains("transferencia")||n.contains("transf");}
 private String[] findBestMoney(String full){Matcher bi=BROU_IMPORTE.matcher(full);if(bi.find())return new String[]{bi.group(1),bi.group(2).trim()};Matcher lm=LABELED_MONEY.matcher(full);if(lm.find())return new String[]{lm.group(1),lm.group(2).trim()};Matcher m=MONEY.matcher(full);if(m.find())return new String[]{m.group(1),m.group(2).trim()};return null;}
 private void processPaganza(StatusBarNotification sbn,String title,String full,String norm){if(!(norm.contains("pago")||norm.contains("pagaste")||norm.contains("pagado")||norm.contains("abonado")||norm.contains("debito")))return;if(norm.contains("rechaz")||norm.contains("fall")||norm.contains("pendiente")||norm.contains("venc")||norm.contains("recordatorio")||norm.contains("devolucion")||norm.contains("anulad"))return;String[]mv=findBestMoney(full);if(mv==null)return;String sym=mv[0],raw=mv[1];double amount=parseLatam(raw.replace(" ",""));if(amount<=0)return;String upper=sym.toUpperCase(Locale.ROOT),currency=(upper.contains("USD")||upper.contains("U$S")||upper.contains("US$"))?"USD":"UYU";String description=title.isEmpty()?"Pago Paganza":title;Matcher sm=PAGANZA_SERVICE.matcher(full);if(sm.find())description=sm.group(1).trim();if(description.toLowerCase(Locale.ROOT).contains("paganza")&&description.length()<18)description="Pago Paganza";long ts=sbn.getPostTime()>0?sbn.getPostTime():System.currentTimeMillis();String unique="";Matcher rm=PAGANZA_REFERENCE.matcher(full);if(rm.find())unique="PAGANZA_REF:"+rm.group(1).trim();if(unique.isEmpty())unique="PAGANZA:"+sbn.getKey();ExpenseDb db=new ExpenseDb(this);if(db.existsOriginal(unique))return;if(NormalDuplicateDetector.hasImportedDuplicate(this,db,"GASTO",amount,currency,description,ts))return;String cat=DetectionRules.categoryFor(this,title+" "+full,classifyPaganza(description));db.addTx("GASTO",amount,currency,cat,description,unique,ts,"notificacion:Paganza");}
 private void saveBankMovement(StatusBarNotification sbn,String title,String full,String sym,String raw,String type){double amount=parseLatam(raw.replace(" ",""));if(amount<=0)return;String upper=sym.toUpperCase(Locale.ROOT),currency=(upper.contains("USD")||upper.contains("U$S")||upper.contains("US$"))?"USD":"UYU";String normalized=normalizeKey(title+" "+full);String description=title.isEmpty()?"Notificación bancaria":title;Matcher cm=BROU_COMERCIO.matcher(full);if(cm.find())description=cm.group(1).trim();else if(normalized.contains("pago de tarjeta"))description="Pago de tarjeta";else description=transferDescriptionFromNotification(title,full,description);long ts=sbn.getPostTime()>0?sbn.getPostTime():System.currentTimeMillis();Matcher em=BROU_EXECUTION_DATE.matcher(full);if(em.find())try{ts=new SimpleDateFormat("dd/MM/yyyy HH:mm:ss",Locale.US).parse(em.group(1)).getTime();}catch(Exception ignored){}else{Matcher fm=BROU_FECHA.matcher(full);if(fm.find())try{ts=new SimpleDateFormat("yyyy-MM-dd HH:mm:ss",Locale.US).parse(fm.group(1)).getTime();}catch(Exception ignored){}}String unique="";Matcher op=BROU_EMAIL_OPERATION.matcher(full);if(op.find())unique="BROU_OPERACION:"+op.group(1).trim();if(unique.isEmpty()){Matcher am=BROU_APROBADO.matcher(full);if(am.find())unique="BROU_APROBADO:"+am.group(1).trim();}if(unique.isEmpty())unique="NOTIF:"+sbn.getKey();ExpenseDb db=new ExpenseDb(this);if(db.existsOriginal(unique))return;if(NormalDuplicateDetector.hasImportedDuplicate(this,db,type,amount,currency,description,ts))return;String defaultCat="INGRESO".equals(type)?"Ingresos":"Sin categoría";String cat=DetectionRules.categoryFor(this,title+" "+full,defaultCat);db.addTx(type,amount,currency,cat,description,unique,ts,"notificacion:"+sbn.getPackageName());}
 private static String transferDescriptionFromNotification(String title,String full,String fallback){String n=normalizeKey(title+" "+full);if(!(n.contains("transferencia")||n.contains("transf")))return fallback;Matcher m=TRANSFER_DETAIL.matcher(full);while(m.find()){String v=m.group(1)==null?"":m.group(1).trim();String nv=normalizeKey(v);if(v.length()>=3&&!nv.equals("transferencia")&&!nv.startsWith("transf"))return"Transferencia · "+v;}String best="";for(String line:full.split("[\\n\\r]+")){String x=line.trim(),nx=normalizeKey(x);if(x.length()<4)continue;if(nx.contains("transferencia")||nx.startsWith("importe")||nx.startsWith("monto")||nx.startsWith("fecha")||nx.startsWith("hora")||nx.startsWith("aprobado")||nx.startsWith("tarjeta")||nx.startsWith("saldo")||MONEY.matcher(x).find())continue;if(x.length()>best.length())best=x;}return best.isEmpty()?fallback:"Transferencia · "+best;}
 private static String classifyPaganza(String d){String s=normalizeKey(d);if(s.contains("ute")||s.contains("ose")||s.contains("antel")||s.contains("movistar")||s.contains("claro")||s.contains("internet"))return"Servicios";if(s.contains("contribucion")||s.contains("tribut")||s.contains("patente")||s.contains("sucive")||s.contains("intendencia"))return"Impuestos";if(s.contains("colegio")||s.contains("escuela")||s.contains("universidad"))return"Educación";if(s.contains("seguro")||s.contains("bse"))return"Seguros";return"Pagos";}private static String normalizeKey(String s){if(s==null)return"";return Normalizer.normalize(s,Normalizer.Form.NFD).replaceAll("\\p{M}","").toLowerCase(Locale.ROOT).replaceAll("\\s+"," ").trim();}private static String collectNotificationText(Bundle e){LinkedHashSet<String>p=new LinkedHashSet<>();add(p,e.getCharSequence(Notification.EXTRA_TITLE));add(p,e.getCharSequence(Notification.EXTRA_TEXT));add(p,e.getCharSequence(Notification.EXTRA_BIG_TEXT));add(p,e.getCharSequence(Notification.EXTRA_SUB_TEXT));add(p,e.getCharSequence(Notification.EXTRA_INFO_TEXT));add(p,e.getCharSequence(Notification.EXTRA_SUMMARY_TEXT));CharSequence[]l=e.getCharSequenceArray(Notification.EXTRA_TEXT_LINES);if(l!=null)for(CharSequence x:l)add(p,x);StringBuilder b=new StringBuilder();for(String x:p){if(b.length()>0)b.append('\n');b.append(x);}return b.toString().trim();}private static void add(Set<String>s,CharSequence x){if(x!=null){String v=x.toString().trim();if(!v.isEmpty())s.add(v);}}private static String s(CharSequence x){return x==null?"":x.toString();}private static double parseLatam(String x){try{int c=x.lastIndexOf(','),d=x.lastIndexOf('.');if(c>=0&&d>=0){if(c>d)x=x.replace(".","").replace(',','.');else x=x.replace(",","");}else if(c>=0)x=x.replace(".","").replace(',','.');else if(d>=0&&x.length()-d-1==3)x=x.replace(".","");return Double.parseDouble(x);}catch(Exception e){return-1;}}
}
